"""JSONL -> token-tensor dataset and deterministic padding."""

from __future__ import annotations

from collections.abc import Iterable
from dataclasses import dataclass

import torch
from torch import Tensor

from tool_use_lab.data import Example, iter_examples
from tool_use_lab.tokenizer import ByteTokenizer


@dataclass(frozen=True)
class TokenizedExample:
    input_ids: Tensor
    labels: Tensor


def encode_example(example: Example, tokenizer: ByteTokenizer, *, block_size: int) -> TokenizedExample:
    prompt_ids = tokenizer.encode(example.prompt, add_bos=True, add_eos=False)
    label_ids = tokenizer.encode(example.canonical_call, add_bos=False, add_eos=True)
    full = prompt_ids + label_ids
    full = full[:block_size]
    labels = [-100] * len(prompt_ids) + label_ids
    labels = labels[:block_size]
    if len(labels) < block_size:
        labels = labels + [-100] * (block_size - len(labels))
    if len(full) < block_size:
        full = full + [tokenizer.pad_id] * (block_size - len(full))
    return TokenizedExample(
        input_ids=torch.tensor(full, dtype=torch.long),
        labels=torch.tensor(labels, dtype=torch.long),
    )


def encode_inputs(examples: Iterable[Example], tokenizer: ByteTokenizer, *, block_size: int) -> Tensor:
    rows: list[Tensor] = []
    for example in examples:
        rows.append(encode_example(example, tokenizer, block_size=block_size).input_ids)
    if not rows:
        return torch.zeros((0, block_size), dtype=torch.long)
    return torch.stack(rows, dim=0)


def encode_labels(examples: Iterable[Example], tokenizer: ByteTokenizer, *, block_size: int) -> Tensor:
    rows: list[Tensor] = []
    for example in examples:
        rows.append(encode_example(example, tokenizer, block_size=block_size).labels)
    if not rows:
        return torch.zeros((0, block_size), dtype=torch.long)
    return torch.stack(rows, dim=0)


def make_batches(inputs: Tensor, labels: Tensor, *, batch_size: int) -> Iterable[tuple[Tensor, Tensor]]:
    n = inputs.shape[0]
    for start in range(0, n, batch_size):
        yield inputs[start : start + batch_size], labels[start : start + batch_size]
