"""Tool-call schema and fail-closed validation."""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class ToolSpec:
    name: str
    description: str
    required: tuple[str, ...]
    optional: tuple[str, ...] = ()


TOOL_SPECS: tuple[ToolSpec, ...] = (
    ToolSpec("route_local", "send work to a local model", ("model",)),
    ToolSpec("route_remote", "send work to a remote model", ("model",)),
    ToolSpec("route_cheap", "send work to a low-cost model", ("model",)),
    ToolSpec("route_quality", "send work to a high-quality model", ("model",)),
    ToolSpec("estimate_tokens", "estimate input tokens", ("text",)),
    ToolSpec("inspect_quota", "inspect provider quota", ("provider",)),
    ToolSpec("retry_request", "retry a failed request", ("request_id",)),
    ToolSpec("reject_request", "reject an unsafe or invalid request", ("reason",)),
)

SPEC_BY_NAME = {spec.name: spec for spec in TOOL_SPECS}


def parse_json_call(text: str) -> dict[str, Any] | None:
    """Parse the final top-level tool-call object without guessing malformed output."""

    decoder = json.JSONDecoder()
    candidates: list[dict[str, Any]] = []
    for index, char in enumerate(text):
        if char != "{":
            continue
        try:
            value, _ = decoder.raw_decode(text[index:])
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            candidates.append(value)
    tool_calls = [candidate for candidate in candidates if "tool" in candidate and "args" in candidate]
    return tool_calls[-1] if tool_calls else (candidates[-1] if candidates else None)


def validate_call(value: Any) -> tuple[bool, list[str]]:
    """Validate a call against the fixed router protocol."""

    errors: list[str] = []
    if not isinstance(value, dict):
        return False, ["call must be an object"]
    if set(value) - {"tool", "args"}:
        errors.append("unknown top-level field")
    tool = value.get("tool")
    args = value.get("args")
    if not isinstance(tool, str) or tool not in SPEC_BY_NAME:
        errors.append("unknown tool")
        return False, errors
    if not isinstance(args, dict):
        return False, errors + ["args must be an object"]
    spec = SPEC_BY_NAME[tool]
    missing = [name for name in spec.required if name not in args]
    unknown = [name for name in args if name not in set(spec.required + spec.optional)]
    if missing:
        errors.append("missing required argument")
    if unknown:
        errors.append("unknown argument")
    for key, item in args.items():
        if not isinstance(item, str) or not item.strip():
            errors.append("argument " + key + " must be non-empty text")
    return not errors, errors


def canonical_call(tool: str, args: dict[str, str]) -> str:
    """Serialize a call deterministically for labels and exact-match eval."""

    value = {"tool": tool, "args": {key: args[key] for key in sorted(args)}}
    return json.dumps(value, ensure_ascii=True, separators=(",", ":"), sort_keys=True)
