import json
import os
import tempfile
from pathlib import Path

import pytest
import requests

from harness_cli_integration_support import (
    assert_file_contains,
    assert_success,
    combined_output,
    gateway_environment,
    gateway_url,
    integration_enabled,
    resolve_command,
    run_command,
)


pytestmark = [
    pytest.mark.integration,
    pytest.mark.harness,
    pytest.mark.skipif(
        not integration_enabled(),
        reason="Set RUN_HARNESS_INTEGRATION_TESTS=1 to run live harness tests",
    ),
]


@pytest.fixture(scope="session", autouse=True)
def gateway_online() -> None:
    try:
        response = requests.get(f"{gateway_url()}/models", timeout=3.0)
    except Exception as error:
        pytest.skip(f"Gateway is not reachable at {gateway_url()}: {error}")
    if response.status_code != 200:
        pytest.skip(f"Gateway returned HTTP {response.status_code} from /models")


INTEGRATION_HARNESSES = ("claude", "dsh")


def command_for(harness: str) -> list[str]:
    explicit_keys = {
        "claude": "CLAUDE_BIN",
        "dsh": "DSH_BIN",
    }
    try:
        return resolve_command(harness, explicit_keys[harness])
    except FileNotFoundError as error:
        pytest.skip(str(error))


def invoke(harness: str, prompt: str, workdir: str, timeout: int = 150):
    environment = gateway_environment()
    command = command_for(harness)
    argv: list[str] = []

    if harness == "claude":
        argv = command + [
            "-p",
            prompt,
            "--output-format",
            "text",
            "--dangerously-skip-permissions",
            "--add-dir",
            workdir,
        ]
    elif harness == "dsh":
        argv = command + [
            "--profile",
            os.environ.get("DSH_PROFILE", "headless"),
            prompt,
        ]
    else:
        raise ValueError(f"Unsupported integration harness: {harness}")

    return run_command(argv, workdir, timeout, environment)


@pytest.mark.parametrize("harness", INTEGRATION_HARNESSES)
def test_harness_connectivity(harness: str):
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as workdir:
        result = invoke(harness, "Reply with only the integer 84.", workdir, timeout=120)
        assert_success(result)
        assert "84" in combined_output(result)


@pytest.mark.parametrize("harness", INTEGRATION_HARNESSES)
def test_harness_file_creation_and_reading(harness: str):
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as workdir:
        prompt = (
            "Create greeting.txt in the current working directory containing "
            "'Hello from Harness Integration', then read it back and print its content."
        )
        result = invoke(harness, prompt, workdir)
        assert_success(result)
        assert_file_contains(workdir, "greeting.txt", "Hello from Harness Integration")


@pytest.mark.parametrize("harness", INTEGRATION_HARNESSES)
def test_harness_file_manipulation_multi_step(harness: str):
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as workdir:
        notes_path = Path(workdir) / "notes.txt"
        notes_path.write_text("Line 1: System Init\n", encoding="utf-8")
        prompt = (
            "Read notes.txt, append 'Line 2: Harness Integration Success' to it, "
            "and print the entire final file."
        )
        result = invoke(harness, prompt, workdir, timeout=180)
        assert_success(result)
        assert_file_contains(
            workdir,
            "notes.txt",
            "Line 1: System Init",
            "Line 2: Harness Integration Success",
        )
