# -*- coding: utf-8 -*-
"""Rewrite all title headings to use correct Chinese numerals."""
from pathlib import Path
import re, glob

DIGITS = "零一二三四五六七八九"

def chinese_num(n):
    """Correctly convert 1-9999 to Chinese number string."""
    if n == 0: return "零"
    parts = []
    if n >= 1000:
        parts.append(DIGITS[n // 1000] + "千")
        n %= 1000
        if n == 0:
            return "".join(parts)
    if n >= 100:
        parts.append(DIGITS[n // 100] + "百")
        n %= 100
        if n == 0:
            return "".join(parts)
    if n >= 10:
        tens = n // 10
        ones = n % 10
        if tens == 1:
            parts.append("十")
        else:
            parts.append(DIGITS[tens] + "十")
        if ones:
            parts.append(DIGITS[ones])
        return "".join(parts)
    if n > 0:
        parts.append(DIGITS[n])
    return "".join(parts)


fixed = 0
for f in sorted(glob.glob("seasons/01-xianxia/chronicle/ch*.md")):
    text = Path(f).read_text(encoding="utf-8")
    chap_m = re.search(r"^chapter:\s*(\d+)", text, re.M)
    if not chap_m: continue
    chap = int(chap_m.group(1))
    expected = f"# 第{chinese_num(chap)}回"
    title_m = re.search(r"^# 第([一-鿿]+)回", text, re.M)
    if not title_m: continue
    actual = title_m.group(0)
    if actual != expected:
        new_text = text.replace(actual, expected, 1)
        Path(f).write_text(new_text, encoding="utf-8")
        fixed += 1
print("titles fixed:", fixed)
'@ | Out-File -LiteralPath "_fix_titles.py" -Encoding utf8
py -3 -X utf8 _fix_titles.py 2>&1

