DIGITS = '零一二三四五六七八九'
def chinese_num(n):
    if n == 0: return '零'
    parts = []
    if n >= 1000:
        parts.append(DIGITS[n // 1000] + '千')
        n %= 1000
    if n >= 100:
        parts.append(DIGITS[n // 100] + '百')
        n %= 100
        if 0 < n < 10:
            parts.append('零')
    if n >= 10:
        tens = n // 10; ones = n % 10
        if tens == 1: parts.append('十')
        else: parts.append(DIGITS[tens] + '十')
        if ones: parts.append(DIGITS[ones])
    elif n > 0 and parts and parts[-1] != '零':
        parts.append(DIGITS[n])
    elif n > 0:
        parts.append(DIGITS[n])
    return ''.join(parts)

rev = {'零':0,'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9}
def parse(s):
    n = 0; cur = 0
    for c in s:
        if c in rev: cur = rev[c]
        elif c == '十': n += cur * 10; cur = 0
        elif c == '百': n += cur * 100; cur = 0
        elif c == '千': n += cur * 1000; cur = 0
    n += cur
    return n

