    $code = $_.Exception.Response.StatusCode.value__
    Write-Host ("[sys={0,6}] HTTP {1}: {2}" -f $sysChars, $code, $_.Exception.Message.Split([char]10)[0])
    $results += [PSCustomObject]@{SysChars=$sysChars; Wall_ms=[int]$sw.ElapsedMilliseconds; Prompt_tok="-"; Completion_tok="-"; RoutedTo="HTTP $code"}
  }
}
$results | Format-Table -AutoSize | Out-String
